head.script:
// 원본 : JLDFIL25910 배당기준일자 신고_저장 및 수정 (/ui/dis/account/JLDFIL25910.xml)

/*
 * 화면 동작
 * 1. 화면 로딩시 업무처리번호가 있으면 상세를 조회, 없으면 등록 모드로 시작
 * 2. 「배당기준일」 구분 선택에 따라 달력과 고정표시 칸을 교체
 * 3. 「찾아보기」 클릭시 첨부파일 선택, 등록된 파일명 클릭시 다운로드
 * 4. 「등록」·「수정」 클릭시 제출 가능 여부 확인과 입력값 검증 후 첨부파일과 함께 저장
 * 5. 「목록」 클릭시 변경된 내용이 있으면 확인 후 목록으로 이동
 *
 * 담긴 패턴
 * - 파라미터 유무로 등록·수정 모드 판정 (버튼 전환)
 * - 안내문구 + 접었다 펴는 입력예시 영역
 * - 선택값에 따라 입력칸 교체 (달력 ↔ 고정표시)
 * - 입력 바이트 카운터 ($c.util.setTextLengthCounter)
 * - 첨부파일 : 등록 전·후 영역 전환, 다운로드, 삭제
 * - 저장 전 서버에 작성 가능 여부 확인
 * - 입력값과 파일을 upload 컴포넌트로 한 번에 전송
 *
 * 변환 샘플과 달라진 곳
 * - 바이트 카운터를 onkeyup 마다 걸던 것을 init 에서 한 번만 건다.
 *   이 공통함수가 안에서 oninput·onchange 를 스스로 bind 하므로,
 *   키를 칠 때마다 다시 부르면 핸들러가 쌓여 입력이 점점 느려진다.
 * - 필수 검증을 항목마다 isEmpty 로 확인하던 것을 $c.data.validateGroup 으로 바꿨다.
 * - submitDoneHandler 옵션과 .catch(() => ({})) 를 걷어내고 await 뒤에서 직접 처리한다.
 *   옵션으로 넘기면 await 가 풀린 뒤에 돌아 이어지는 코드와 순서가 어긋난다.
 * - 저장 응답이 실패로 와도 아무 반응이 없던 것을 안내하도록 고쳤다.
 * - $c.win.confirm 을 콜백 대신 await 로 받는다.
 */


///////// 1. 변수 및 선언 영역 /////////

scwin.screenId = "JLDFIL25910";


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 08. 19
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
	// 초기화 함수
	await scwin.init();
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 08. 19
 * @description 초기화. 업무처리번호 유무로 등록·수정 모드를 정하고 상세를 조회한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 받는 파라미터 이름
 *  - 달력 컴포넌트 id
 *  - 바이트 카운터 대상과 최대 길이
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
	// 이전 화면에서 전달받은 업무처리번호. 없으면 등록, 있으면 수정이다.
	const bzProcsNo = $c.data.getParameter("bzProcsNo");

	// 등록·수정 모드별 화면 설정
	scwin.setScreenMode(bzProcsNo);

	// 달력에 형식 검증을 걸어 둔다. 직접 타이핑한 값도 이 검증을 탄다.
	$c.date.checkCalendarFormat("cal_divBasDd", "yyyyMMdd");

	// 바이트 카운터는 여기서 한 번만 건다.
	// 이 공통함수가 안에서 oninput·onchange 를 스스로 bind 하고 즉시 한 번 그린다.
	// onkeyup 마다 다시 부르면 키를 칠 때마다 핸들러가 쌓여 입력이 점점 느려진다.
	// 한글은 한 글자가 여러 바이트라 DB 가 바이트로 자르면 checkType 을 byte 로 둔다.
	$c.util.setTextLengthCounter(ipt_shrhdNmlistClsBasddContn, txt_shrhdNmlistClsBasddContnCnt, {
		maxLength : 4000, checkType : "byte", warnClass : "warn"
	});
	$c.util.setTextLengthCounter(ipt_proftDivRemk, txt_proftDivRemkCnt, {
		maxLength : 4000, checkType : "byte", warnClass : "warn"
	});

	// 등록 모드면 조회할 것이 없다.
	if ($c.util.isEmpty(bzProcsNo)) return;

	await scwin.selectDivBasDdInfo(bzProcsNo);
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_info_onclick
 * @author Inswave
 * @date 2026. 08. 19
 * @description 입력예시 보기 클릭. 예시 영역을 접었다 편다.
 *
 * 안내가 길면 화면이 밀리므로 평소에는 접어 둔다.
 * 지금 접혀 있는지 펴져 있는지는 클래스로 기억한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_info_onclick = function (e) {
	grp_info.toggleClass("active");

	if (grp_info.hasClass("active")) {
		grp_info.show("");
	} else {
		grp_info.hide();
	}
};

/**
 * @event
 * @name scwin.rd_divBasDdYn_onchange
 * @author Inswave
 * @date 2026. 08. 19
 * @description 배당기준일 구분 변경. 값에 따라 입력칸을 바꿔 끼운다.
 *
 * 라디오는 컴포넌트마다 이벤트 인자가 달라 값을 getValue() 로 읽는 편이 안전하다.
 * onviewchange 는 newValue 가 없고 value 를 넘긴다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 교체할 두 컴포넌트
 * @param
 * @returns
 * @hidden N
*/
scwin.rd_divBasDdYn_onchange = function (info) {
	// 구분이 바뀌면 이전에 고른 일자는 의미가 없다. 남겨 두면 보이지 않는 값이 저장된다.
	cal_divBasDd.setValue("");

	scwin.setDivBasDdInput(rd_divBasDdYn.getValue());
};

/**
 * @event
 * @name scwin.cal_divBasDd_onblur
 * @author Inswave
 * @date 2026. 08. 19
 * @description 배당기준일에서 포커스가 빠질 때 날짜 형식을 확인한다.
 *
 * 달력으로 고르면 형식이 맞지만 직접 타이핑할 수 있으므로 여기서 한 번 더 본다.
 * 컴포넌트 이름을 적지 않고 this 로 받으면 다른 달력에도 그대로 쓸 수 있다.
 * @param
 * @returns
 * @hidden N
*/
scwin.cal_divBasDd_onblur = function () {
	const value = $c.str.trim(this.getValue());

	if ($c.util.isEmpty(value)) return;

	if (!$c.date.isDate(value, false)) {
		$c.win.alert(this.getAttribute("title") + " : 날짜는 8자리 yyyyMMdd 형식입니다.");
	}
};

/**
 * @event
 * @name scwin.txt_attachFileNm_onclick
 * @author Inswave
 * @date 2026. 08. 19
 * @description 등록된 첨부파일명 클릭. 파일을 내려받는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.txt_attachFileNm_onclick = function (e) {
	scwin.downloadAttachFile();
};

/**
 * @event
 * @name scwin.btn_deleteFile_onclick
 * @author Inswave
 * @date 2026. 08. 19
 * @description 파일 삭제 버튼 클릭. 첨부 영역을 등록 전 상태로 되돌린다.
 *
 * 화면에서만 지운다. 서버 파일은 새 파일과 함께 저장할 때 정리된다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_deleteFile_onclick = function (e) {
	dma_divBasDdInfo.set("attachFileNm", "");

	scwin.setAttachFileMode(true);
};

/**
 * @event
 * @name scwin.btn_fileUp_onclick
 * @author Inswave
 * @date 2026. 08. 19
 * @description 찾아보기 버튼 클릭. 파일 선택창을 연다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_fileUp_onclick = function (e) {
	// 공통 함수가 업로드 컴포넌트 내부 input 을 클릭해 파일 대화상자를 연다.
	$c.util.onUploadClick(upd_compUpload);
};

/**
 * @event
 * @name scwin.upd_compUpload_onInputValueChange
 * @author Inswave
 * @date 2026. 08. 19
 * @description 파일을 고른 순간 파일명을 화면에 표시한다.
 *
 * upload 는 고른 파일명을 인자로 그대로 넘겨준다.
 * multiupload 처럼 목록을 다시 꺼내 마지막 항목을 찾을 필요가 없다.
 * @param
 * @returns
 * @hidden N
*/
scwin.upd_compUpload_onInputValueChange = function (fileName) {
	txt_presentAttachFile.setValue(fileName);
};

/**
 * @event
 * @name scwin.btn_list_onclick
 * @author Inswave
 * @date 2026. 08. 19
 * @description 목록 버튼 클릭. 저장하지 않고 목록으로 돌아간다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_list_onclick = async function (e) {
	// 고친 내용이 있는지 공통함수로 확인한다. 화면에서 값을 하나씩 비교하지 않는다.
	// 인자는 DataCollection 객체나 그 배열이다. 아이디 문자열을 넘기면 항상 false 가 된다.
	if ($c.data.isModified([dma_divBasDdInfo])) {
		if (!await $c.win.confirm("저장하지 않은 내용이 있습니다. 목록으로 이동하시겠습니까?")) return;
	}

	scwin.goList();
};

/**
 * @event
 * @name scwin.btn_register_onclick
 * @author Inswave
 * @date 2026. 08. 19
 * @description 등록 버튼 클릭
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_register_onclick = async function (e) {
	await scwin.register();
};

/**
 * @event
 * @name scwin.btn_update_onclick
 * @author Inswave
 * @date 2026. 08. 19
 * @description 수정 버튼 클릭. 등록과 하는 일이 같아 같은 함수를 부른다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_update_onclick = async function (e) {
	await scwin.register();
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.selectDivBasDdInfo
 * @author Inswave
 * @date 2026. 08. 19
 * @description 상세를 조회해 dma_divBasDdInfo 에 담는다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action 경로, target
 * @param
 * @returns
 * @hidden N
*/
scwin.selectDivBasDdInfo = async function (bzProcsNo) {
	dma_divBasDdInfo.set("bzProcsNo", bzProcsNo);

	const sbmOptions = {
		id : "sbm_selectContent",
		method : "get",
		action : "/api/discls/info/div-bas-dd/select-one",
		ref : "dma_divBasDdInfo",
		target : "dma_divBasDdInfo=body",
		isProcessMsg : false
	};

	// 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
	// 여기서 잡지 않으므로 오류가 나면 아래 처리는 실행되지 않는다.
	const result = await $c.sbm.executeDynamic(sbmOptions);

	// 조회 결과 처리는 submitDoneHandler 옵션 대신 여기서 직접 부른다.
	// 옵션으로 넘기면 await 가 풀린 뒤에 돌아 이어지는 코드와 순서가 어긋난다.
	scwin.sbm_selectContent_submitdone(result);
};

/**
 * @method
 * @name scwin.sbm_selectContent_submitdone
 * @author Inswave
 * @date 2026. 08. 19
 * @description 상세 조회 완료. 조회된 값에 맞춰 화면을 맞춘다.
 *
 * submitDoneHandler 옵션이 아니라 조회 함수의 await 뒤에서 직접 부른다.
 * 이름을 _submitdone 으로 두는 것은 어느 통신의 후처리인지 드러내기 위해서다.
 * @param
 * @returns
 * @hidden N
*/
scwin.sbm_selectContent_submitdone = function (e) {
	const body = e.responseJSON?.body ?? {};

	// 구분에 맞는 입력칸을 보여 준다.
	scwin.setDivBasDdInput(body.divBasDdYn);

	// 첨부가 없으면 등록 영역을, 있으면 다운로드 영역을 보여 준다.
	scwin.setAttachFileMode($c.util.isEmpty(body.attachFileNm));
};

/**
 * @event
 * @name scwin.upd_compUpload_ondone
 * @author Inswave
 * @date 2026. 08. 19
 * @description 저장 완료. 목록으로 돌아간다.
 *
 * upload 의 응답은 xml 로 온다. ret 태그 안에 결과 json 이 문자열로 들어 있다.
 * 통신 자체가 실패하면 이 이벤트는 오지 않는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.upd_compUpload_ondone = function (responseXML) {
	const ret = responseXML.getElementsByTagName("ret")[0]?.textContent;
	const result = $c.util.getJSON(ret);

	// 실패도 알린다. 그냥 return 하면 사용자는 저장된 줄 안다.
	if (!result?.success) {
		$c.win.alert($c.data.getMessage("com_complete_0151", "저장"));
		return;
	}

	$c.win.alert($c.data.getMessage("com_complete_0150", "저장"), () => { scwin.goList(); });
};

/**
 * @method
 * @name scwin.checkDeclarable
 * @author Inswave
 * @date 2026. 08. 19
 * @description 지금 작성할 수 있는 상태인지 서버에 묻는다.
 *
 * 기간이 지났거나 이미 제출한 건을 화면에서 알 수 없을 때 쓴다.
 * 저장을 눌러 실패로 알리는 것보다 미리 막는 편이 낫다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action 경로, 응답 코드의 뜻
 * @param
 * @returns
 * @hidden N
*/
scwin.checkDeclarable = async function () {
	const sbmOptions = {
		id : "sbm_selectDeclTp",
		method : "get",
		action : "/api/discls/info/div-bas-dd/decl-tp/select-one",
		isProcessMsg : false
	};

	// 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
	const result = await $c.sbm.executeDynamic(sbmOptions);

	// N 제출 시간 초과
	if (result.responseJSON?.body === "N") {
		await $c.win.alert("제출 시간을 초과했습니다.");
		return false;
	}

	return true;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.setScreenMode
 * @author Inswave
 * @date 2026. 08. 19
 * @description 등록·수정 모드에 따라 버튼과 첨부 영역을 정한다.
 *
 * 모드 판정을 한 곳에 모아 두면 화면 곳곳에 같은 조건문이 흩어지지 않는다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 모드별로 보일 버튼
 * @param
 * @returns
 * @hidden N
*/
scwin.setScreenMode = function (bzProcsNo) {
	const isUpdate = $c.util.isNotEmpty(bzProcsNo);

	if (isUpdate) {
		btn_update.show("");
		return;
	}

	btn_register.show("");

	// 등록 모드에는 기존 첨부가 없으므로 그 영역을 감춘다.
	grp_quesAttachFile.hide();
};

/**
 * @method
 * @name scwin.setDivBasDdInput
 * @author Inswave
 * @date 2026. 08. 19
 * @description 구분에 따라 달력과 고정표시 칸을 바꿔 끼운다.
 *
 * show 는 반드시 인자를 주어 부른다. 인자 없이 부르면 display:block 이 되어
 * 표 안의 칸이 줄바꿈되며 배치가 무너진다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 교체할 두 컴포넌트
 * @param
 * @returns
 * @hidden N
*/
scwin.setDivBasDdInput = function (divBasDdYn) {
	// Y 특정일자로 정한 경우 · N 이사회결의로 정하는 경우
	const isFixedDate = divBasDdYn !== "N";

	if (isFixedDate) {
		cal_divBasDd.show("");
		ipt_divBasDd.hide();
		return;
	}

	cal_divBasDd.hide();
	ipt_divBasDd.show("");
};

/**
 * @method
 * @name scwin.goList
 * @author Inswave
 * @date 2026. 08. 19
 * @description 목록 화면으로 이동한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 목록 화면 경로
 * @param
 * @returns
 * @hidden N
*/
scwin.goList = function () {
	$c.win.moveUrl("/ui/sample/template/JLDFIL25900.xml", {});
};

/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 08. 19
 * @description 작성 가능 여부를 확인하고 검증한 뒤 저장한다.
 *
 * 순서가 중요하다. 먼저 서버에 물어 기간이 지났는지 확인하고,
 * 그 다음 입력값을 검증하고, 마지막에 사용자 확인을 받는다.
 * 검증부터 하면 기간이 지난 건에도 입력을 요구하게 된다.
 * @param
 * @returns
 * @hidden N
*/
scwin.register = async function () {
	if (!await scwin.checkDeclarable()) return;

	if (!await scwin.validate()) return;

	if (!await $c.win.confirm($c.data.getMessage("com_crud_0198", "저장"))) return;

	scwin.upload();
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 08. 19
 * @description 저장 전 입력값을 검증한다.
 *
 * 필수·자리수 검증은 공통함수 $c.data.validateGroup 이 안내와 포커스까지 처리한다.
 * 항목마다 isEmpty 로 확인하고 alert 을 띄우던 코드를 대신한다.
 * id 는 컴포넌트가 ref 로 묶인 DataMap 의 키다.
 *
 * 공통함수로 표현할 수 없는 조건부 검증만 아래에 이어서 쓴다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - valInfo 항목
 * @param
 * @returns
 * @hidden N
*/
scwin.validate = async function () {
	const valInfo = [
		{ id : "shrhdNmlistClsBasddContn", mandatory : true },
		{ id : "proftDivRemk", mandatory : true }
	];

	if (!await $c.data.validateGroup(grp_form, valInfo)) return false;

	// 배당기준일은 특정일자를 고른 경우에만 필수다. 조건이 붙어 valInfo 로 표현할 수 없다.
	if (rd_divBasDdYn.getValue() === "Y") {
		if ($c.util.isEmpty(cal_divBasDd.getValue())) {
			await $c.win.alert($c.data.getMessage("com_crud_0199", "배당기준일"));
			cal_divBasDd.focus();
			return false;
		}

		if (!$c.date.checkCalendarFormat(cal_divBasDd, "yyyyMMdd")) {
			await $c.win.alert("yyyyMMdd 형식의 올바른 날짜를 입력하세요.");
			cal_divBasDd.focus();
			return false;
		}
	}

	// 첨부파일은 등록할 때만 필수다. 수정은 기존 파일을 그대로 둘 수 있다.
	const isNew = $c.util.isEmpty(dma_divBasDdInfo.get("bzProcsNo"));

	if (isNew && $c.util.isEmpty(txt_presentAttachFile.getValue())) {
		await $c.win.alert($c.data.getMessage("com_crud_0199", "첨부파일"));
		return false;
	}

	return scwin.validateAttachFile();
};

/**
 * @method
 * @name scwin.validateAttachFile
 * @author Inswave
 * @date 2026. 08. 19
 * @description 고른 파일의 확장자와 파일명 길이를 확인한다.
 *
 * 확장자 검사는 공통함수를 쓴다. 화면에서 배열을 직접 돌며 비교하지 않는다.
 * 안내 문구까지 공통함수가 띄운다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 허용 확장자, 파일명 최대 길이
 * @param
 * @returns
 * @hidden N
*/
scwin.validateAttachFile = function () {
	const fileName = upd_compUpload.getValue();

	// 고른 파일이 없으면 볼 것이 없다. 수정하면서 기존 파일을 그대로 두는 경우다.
	if ($c.util.isEmpty(fileName)) return true;

	const allowExt = ["drt", "bmp", "gif", "jpeg", "jpg", "png",
		"hwp", "docx", "doc", "xls", "xlsx", "ppt", "pptx", "pdf", "zip", "txt"];

	const extAlertMsg = "첨부할 수 없는 확장자를 가진 파일이 있습니다.\n사용가능 확장자 : " + allowExt.join(", ");

	if (!$c.util.checkFileExtension(fileName, allowExt, extAlertMsg)) return false;

	// 파일명 길이는 바이트로 잰다. 한글 파일명은 글자수와 바이트가 다르다.
	if ($c.str.getByteLength(fileName) > 80) {
		$c.win.alert("파일명 길이가 80byte 를 넘는 파일이 있습니다.");
		return false;
	}

	return true;
};

/**
 * @method
 * @name scwin.setAttachFileMode
 * @author Inswave
 * @date 2026. 08. 19
 * @description 첨부 영역을 등록 전·후 상태로 전환한다.
 *
 * show 는 반드시 인자를 주어 부른다. 인자 없이 부르면 display:block 이 되어
 * flex 로 나란히 놓은 항목이 세로로 쌓인다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 전환할 영역
 * @param
 * @returns
 * @hidden N
*/
scwin.setAttachFileMode = function (isUploadable) {
	if (isUploadable) {
		// 등록된 파일 없음 : 업로드 영역을 연다.
		grp_attachFile.hide();
		grp_nofileMessage.show("");
		grp_upload.show("");
		grp_message.hide();
		return;
	}

	// 등록된 파일 있음 : 파일명과 삭제 안내를 보여 주고 업로드를 막는다.
	grp_attachFile.show("flex");
	grp_nofileMessage.hide();
	grp_upload.hide();
	grp_message.show("");
};

/**
 * @method
 * @name scwin.downloadAttachFile
 * @author Inswave
 * @date 2026. 08. 19
 * @description 저장된 첨부파일을 내려받는다.
 *
 * $c.data.downFile 은 async 라 실패 시 reject 한다.
 * catch 를 붙이지 않으면 서버가 죽어 있어도 화면에 아무 반응이 없다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 내려받기 경로, 파라미터
 * @param
 * @returns
 * @hidden N
*/
scwin.downloadAttachFile = async function () {
	const fileName = dma_divBasDdInfo.get("attachFileNm");

	if ($c.util.isEmpty(fileName)) return;

	await $c.data.downFile("/api/discls/info/div-bas-dd/file/download", fileName, {
		bzProcsNo : dma_divBasDdInfo.get("bzProcsNo")
	}).catch(() => { $c.win.alert("파일을 내려받지 못했습니다."); });
};

/**
 * @method
 * @name scwin.upload
 * @author Inswave
 * @date 2026. 08. 19
 * @description 입력값을 실어 파일과 함께 보낸다.
 *
 * upload 는 addParam 으로 값을 싣고 submit() 으로 보낸다.
 * 보낼 주소는 마크업의 action 에 적어 두었다.
 * 결과는 ondone 이 받는다. 여기서 await 로 기다릴 수 없다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 서버가 받는 항목명
 * @param
 * @returns
 * @hidden N
*/
scwin.upload = function () {
	// 서버가 받는 항목명이다. 화면 id 가 아니라 전문 규격을 그대로 적는다.
	["bzProcsNo", "divBasDdYn", "divBasDd", "shrhdNmlistClsBasddContn", "proftDivRemk"].forEach(key => {
		upd_compUpload.addParam(key, dma_divBasDdInfo.get(key));
	});

	upd_compUpload.submit();
};
